package com.studentgrade.controller;
import com.studentgrade.dto.AuthDtos.*; import com.studentgrade.service.ResultService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/results") public class ResultController { private final ResultService service; public ResultController(ResultService s){this.service=s;} @PostMapping("/calculate") @ResponseStatus(HttpStatus.CREATED) public ResultResponse calculate(Authentication a,@Valid @RequestBody ResultRequest r){return service.calculate(a.getName(),r);} @GetMapping public List<ResultResponse> list(Authentication a){return service.list(a.getName());} @GetMapping("/{id}") public ResultResponse get(Authentication a,@PathVariable Long id){return service.get(a.getName(),id);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(Authentication a,@PathVariable Long id){service.delete(a.getName(),id);} }